              tableHtml += '<td class="text-center px-1 py-2 text-xs border-l border-stone-100 ' + (isWeekend ? 'bg-stone-50' : '') + '"><div class="text-emerald-600 font-medium">' + (h.masuk || '?') + '</div><div class="text-stone-400">' + (h.keluar || '?') + '</div></td>';
