function fmtDateIndonesia(dateStr) {
  if (!dateStr) return '—';
  const d = new Date(dateStr + 'T00:00:00');
  const hari = ['Minggu','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'];
  const bulan = ['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
  return hari[d.getDay()] + ', ' + d.getDate() + ' ' + bulan[d.getMonth()] + ' ' + d.getFullYear();
}
// ===== Payroll Mingguan Helpers =====
function pmGanti() {
  lapState.pm_bulan = document.getElementById('pm-bulan')?.value;
  lapState.pm_tahun = document.getElementById('pm-tahun')?.value;
  lapState.pm_minggu = parseInt(document.getElementById('pm-minggu')?.value || '1');
  showLap('payroll-mingguan');
}

async function exportPayrollMingguanLap() {
  var data = window._pmExportData;
  if (!data || !data.karyawan || !data.karyawan.length) return showAlert('Tidak ada data', 'warning');

  var { minggu, karyawan } = data;
  var tglNama = ['Min','Sen','Sel','Rab','Kam','Jum','Sab'];

  var headers = ['Nama Karyawan', 'Jabatan'];
  minggu.dates.forEach(function(tgl) {
    var d = new Date(tgl + 'T00:00:00');
    var label = tglNama[d.getDay()] + ' ' + tgl.slice(8,10) + '/' + tgl.slice(5,7);
    headers.push(label + ' Masuk', label + ' Keluar');
  });
  headers.push('Total Hadir', 'Upah/Hari', 'Total Gaji');

  var rows = karyawan.map(function(k) {
    var row = [k.nama, k.jabatan];
    k.harian.forEach(function(h) {
      if (h && h.status === 'Hadir') row.push(h.masuk || '-', h.keluar || '-');
      else if (h) row.push(h.status, '-');
      else row.push('-', '-');
    });
    row.push(k.total_hadir, k.upah_per_hari, k.total_gaji);
    return row;
  });

  var totalHadir = karyawan.reduce(function(s, k) { return s + k.total_hadir; }, 0);
  var totalGaji = karyawan.reduce(function(s, k) { return s + k.total_gaji; }, 0);
  var totalRow = ['TOTAL', ''];
  minggu.dates.forEach(function() { totalRow.push('', ''); });
  totalRow.push(totalHadir, '', totalGaji);
  rows.push(totalRow);

  var wsData = [headers].concat(rows);
  var ws = XLSX.utils.aoa_to_sheet(wsData);
  var colWidths = [{ wch: 28 }, { wch: 18 }];
  minggu.dates.forEach(function() { colWidths.push({ wch: 10 }, { wch: 10 }); });
  colWidths.push({ wch: 10 }, { wch: 12 }, { wch: 14 });
  ws['!cols'] = colWidths;

  var wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Payroll Mingguan');
  var filename = 'payroll-mingguan-' + minggu.label.replace(/[\s,()]/g, '_') + '.xlsx';
  XLSX.writeFile(wb, filename);
}

async function bayarPayrollMingguanLap() {
  var bln = document.getElementById('pm-bulan')?.value || '';
  var thn = document.getElementById('pm-tahun')?.value || '';
  var mgg = document.getElementById('pm-minggu')?.value || '1';
  if (!bln || !thn) return showAlert('Pilih bulan & tahun', 'warning');

  if (!await showConfirm('Bayar payroll mingguan ini? Jurnal otomatis akan dibuat di Kas Bank.', 'Ya, Bayar')) return;

  try {
    var res = await api.post('/payroll/mingguan/bayar', { bulan: parseInt(bln), tahun: parseInt(thn), minggu_ke: parseInt(mgg) });
    if (res.ok) {
      showToast('✅ ' + res.pesan, 'success');
      showLap('payroll-mingguan'); // refresh
    }
  } catch (e) {
    if (e.status === 409) {
      showAlert('Jurnal sudah ada (No. ' + (e.data?.no_transaksi || '') + ')', 'warning');
    } else {
      showAlert('Gagal: ' + (e.message || ''), 'error');
    }
  }
}

function editSaldoAwal(current) {
  const amount = prompt('Masukkan Saldo Awal Buku (Rp):', fmtIDR(current).replace(/[^0-9]/g,''));
  if (amount === null) return;
  const val = parseFloat(amount.replace(/[^0-9.]/g,''));
  if (isNaN(val) || val < 0) return showAlert('Nilai tidak valid', 'error');
  api.put('/keuangan/saldo-awal', { saldo_awal: val }).then(r => {
    if (r.ok) { showAlert('Saldo awal berhasil disimpan', 'success'); showLap('keuangan'); }
  }).catch(e => showAlert('Gagal: ' + e.message, 'error'));
}

function renderDailyMenuTable(menuHarian, kategori_order) {
  const siklus = menuHarian || [];
  if (!siklus.length) return '<div class="p-8 text-center text-stone-400">Belum ada data siklus</div>';

  const KAT_MAP = { Karbohidrat: 'Makanan Pokok', 'Protein Hewani': 'Lauk Hewani', 'Protein Nabati': 'Lauk Nabati', Sayur: 'Sayur', Buah: 'Buah', Susu: 'Susu', Minyak: 'Minyak' };
  const ROW_KEYS = ['Karbohidrat', 'Protein Hewani', 'Protein Nabati', 'Sayur', 'Buah', 'Susu'];
  const ROW_LABELS = ROW_KEYS.map(k => KAT_MAP[k] || k);

  let maxHari = 0;
  for (const s of siklus) {
    for (const d of s.days) {
      if (d.hari_ke > maxHari) maxHari = d.hari_ke;
    }
  }
  if (!maxHari) return '<div class="p-8 text-center text-stone-400">Belum ada hari terisi</div>';

  const dayKeys = Array.from({ length: maxHari }, (_, i) => i + 1);

  let html = '<div class="overflow-x-auto text-xs leading-relaxed">';
  html += '<table class="w-full border-collapse border border-stone-300">';

  html += '<thead>';
  html += '<tr class="bg-amber-400 text-center font-bold">';
  html += '<th class="border border-stone-300 px-3 py-2 text-[11px]" style="color:#000">Kelompok Bahan Makanan</th>';
  for (const k of dayKeys) {
    const dayNama = kategori_order && siklus.length && siklus[0].days[k-1] ? siklus[0].days[k-1].hari_nama : '';
    html += `<th class="border border-stone-300 px-3 py-2 text-center text-[11px]" style="color:#000">Menu ${k}<br><span class="text-[10px] font-normal">${dayNama}</span></th>`;
  }
  html += '</tr>';
  html += '</thead>';

  html += '<tbody>';

  for (let ri = 0; ri < ROW_KEYS.length; ri++) {
    const rowLabel = ROW_LABELS[ri];
    const isFirst = ri === 0;

    html += `<tr class="border border-stone-300 ${isFirst ? 'bg-sky-50' : ''}">`;
    html += `<td class="border border-stone-300 px-3 py-2 font-bold ${isFirst ? 'bg-sky-50' : ''}">${rowLabel}</td>`;

    for (const k of dayKeys) {
      const names = [];
      for (const s of siklus) {
        for (const d of s.days) {
          if (d.hari_ke === k) {
            const katItems = d.kategori && d.kategori[ROW_KEYS[ri]];
            if (katItems && katItems.length) {
              for (const n of katItems) {
                if (!names.includes(n)) names.push(n);
              }
            }
          }
        }
      }
      let cell = '<span class="text-stone-300">-</span>';
      if (names.length) {
        cell = names.map(n => `<div class="text-[10px] py-0.5">${n}</div>`).join('');
      }
      html += `<td class="border border-stone-300 px-3 py-2 align-top">${cell}</td>`;
    }
    html += '</tr>';
  }

  html += '</tbody></table></div>';
  return html;
}

function renderResepTable(siklus, kategori_order) {
  if (!siklus.length) return '<div class="p-8 text-center text-stone-400">Tidak ada siklus aktif</div>';

  const KAT_MAP = { Karbohidrat: 'Makanan Pokok', 'Protein Hewani': 'Lauk Hewani', 'Protein Nabati': 'Lauk Nabati', Sayur: 'Sayur', Buah: 'Buah', Susu: 'Susu', Minyak: 'Minyak' };
  const ROW_KEYS = ['Karbohidrat', 'Protein Hewani', 'Protein Nabati', 'Sayur', 'Buah', 'Susu'];

  // Flatten all days from all siklus, group by hari_ke
  const byDay = {};
  for (const s of siklus) {
    for (const d of s.days) {
      if (!d.menu_id) continue;
      const key = d.hari_ke;
      if (!byDay[key]) {
        byDay[key] = { hari_ke: d.hari_ke, hari_nama: d.hari_nama, catNames: {} };
        for (const rk of ROW_KEYS) byDay[key].catNames[rk] = [];
      }
      const parts = (d.menu_nama || '').split(/[+,]/).map(s => s.trim()).filter(Boolean);
      const catWithItems = ROW_KEYS.filter(k2 => d.kategori && d.kategori[k2] && d.kategori[k2].length > 0);
      let pi = 0;
      for (const ck of catWithItems) {
        const name = pi < parts.length ? parts[pi] : (d.menu_nama || '');
        if (!byDay[key].catNames[ck].includes(name)) byDay[key].catNames[ck].push(name);
        pi++;
      }
    }
  }

  const dayKeys = Object.keys(byDay).sort((a, b) => Number(a) - Number(b));
  if (!dayKeys.length) return '<div class="p-8 text-center text-stone-400">Belum ada data menu terisi</div>';

  let html = '<div class="overflow-x-auto">';
  html += '<table class="w-full border-collapse border border-stone-300 text-xs">';
  html += '<thead>';
  html += '<tr class="bg-amber-400 text-center font-bold">';
  html += '<th class="border border-stone-300 px-3 py-2 text-[11px]" style="color:#000">Kelompok Bahan Makanan</th>';
  for (const k of dayKeys) {
    const d = byDay[k];
    html += `<th class="border border-stone-300 px-3 py-2 text-center text-[11px]" style="color:#000">Menu ${k}<br><span class="text-[10px] font-normal">${d.hari_nama}</span></th>`;
  }
  html += '</tr>';
  html += '</thead>';
  html += '<tbody>';

  for (let ri = 0; ri < ROW_KEYS.length; ri++) {
    const rk = ROW_KEYS[ri];
    const label = KAT_MAP[rk] || rk;
    const isFirst = ri === 0;
    html += `<tr class="border border-stone-300 ${isFirst ? 'bg-emerald-50' : ''}">`;
    html += `<td class="border border-stone-300 px-3 py-2 font-bold ${isFirst ? 'bg-emerald-50' : ''}">${label}</td>`;

    for (const k of dayKeys) {
      const d = byDay[k];
      const names = d.catNames[rk];
      const cell = names.length
        ? names.map(n => `<div class="py-0.5 font-medium text-teal-700">${n}</div>`).join('')
        : '<span class="text-stone-300">—</span>';
      html += `<td class="border border-stone-300 px-3 py-2 align-top">${cell}</td>`;
    }
    html += '</tr>';
  }

  html += '</tbody></table></div>';
  return html;
}




// ===== Siklus Menu =====
const HARI_OPTIONS = ['Senin','Selasa','Rabu','Kamis','Jumat','Sabtu','Minggu'];

const KAT_SP_ORDER = ['Karbohidrat','Protein Hewani','Protein Nabati','Sayur','Buah','Susu','Minyak'];
const KAT_SP_LABELS = {
  'Karbohidrat': { label: 'Karbohidrat', color: 'text-amber-700 bg-amber-50' },
  'Protein Hewani': { label: 'Protein Hewani', color: 'text-red-700 bg-red-50' },
  'Protein Nabati': { label: 'Protein Nabati', color: 'text-emerald-700 bg-emerald-50' },
  'Sayur': { label: 'Sayur', color: 'text-green-700 bg-green-50' },
  'Buah': { label: 'Buah', color: 'text-orange-700 bg-orange-50' },
  'Susu': { label: 'Susu', color: 'text-blue-700 bg-blue-50' },
  'Minyak': { label: 'Minyak', color: 'text-yellow-700 bg-yellow-50' },
};

async function getMenuKategoriBreakdown(menuId) {
  if (!menuId) return null;
  try {
    const menu = await api.get('/menu/' + menuId);
    const groups = {};
    for (const b of (menu.bahan || [])) {
      const kat = b.kategori_sp || 'Lainnya';
      if (!groups[kat]) groups[kat] = [];
      groups[kat].push(b);
    }
    return groups;
  } catch { return null; }
}

function renderKategoriBreakdown(groups) {
  if (!groups) return '';
  const total = Object.keys(groups).reduce((s, k) => s + groups[k].length, 0);
  if (!total) return '';
  let html = '<div class="mt-1.5 space-y-0.5 bg-stone-50 rounded-lg p-2 border border-stone-100">';
  for (const kat of KAT_SP_ORDER) {
    const items = groups[kat];
    if (!items || !items.length) continue;
    const lbl = KAT_SP_LABELS[kat] || { label: kat, color: 'text-stone-700 bg-stone-50' };
    const names = items.map(b => b.nama + (b.jumlah ? ' ' + b.jumlah + 'g' : '')).join(', ');
    html += '<div class="flex items-center gap-1.5 text-[11px] leading-tight"><span class="inline-block px-1.5 py-0.5 rounded font-medium whitespace-nowrap ' + lbl.color + '">' + lbl.label + '</span><span class="text-stone-500 truncate">' + names + '</span></div>';
  }
  html += '</div>';
  return html;
}

async function renderSiklus() {
  const c = document.getElementById('content');
  c.innerHTML = '<div class="flex items-center justify-center py-24"><svg class="animate-spin h-10 w-10 text-[#1e40af]" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"/><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"/></svg></div>';
  try {
    await preloadMenus();
    const r = await fetch('/api/template/siklus', { credentials: 'include' });
    if (!r.ok) {
      const err = await r.json();
      throw new Error(err.error || 'Gagal memuat siklus');
    }
    c.innerHTML = await r.text();

    // Attach search & filter handlers
    const searchInput = document.getElementById('siklus-search');
    const filterSelect = document.getElementById('siklus-filter-status');
    const debounceTimer = { id: null };
    if (searchInput) {
      searchInput.addEventListener('input', function() {
        clearTimeout(debounceTimer.id);
        debounceTimer.id = setTimeout(() => reloadSiklusList(), 300);
      });
    }
    if (filterSelect) {
      filterSelect.addEventListener('change', () => reloadSiklusList());
    }

    reloadSiklusList();
  } catch (err) {
    console.error('Siklus error:', err);
    c.innerHTML = `<div class="bg-red-50 border border-red-200 text-red-700 p-4 rounded-lg">Gagal memuat siklus: ${err.message}</div>`;
  }
}

async function reloadSiklusList() {
  let list = await api.get('/siklus');
  const wrap = document.getElementById('siklus-list');
  if (!wrap) return;

  // Filter by search
  const searchVal = (document.getElementById('siklus-search')?.value || '').toLowerCase();
  const filterStatus = document.getElementById('siklus-filter-status')?.value || '';

  if (searchVal) {
    list = list.filter(s =>
      (s.nama || '').toLowerCase().includes(searchVal) ||
      (s.kategori_penerima || '').toLowerCase().includes(searchVal) ||
      (s.catatan || '').toLowerCase().includes(searchVal)
    );
  }
  if (filterStatus) {
    list = list.filter(s => s.status === filterStatus);
  }

  // Update stats
  const statsEl = document.getElementById('siklus-stats');
  if (statsEl) {
    const total = list.length;
    const aktif = list.filter(s => s.status === 'Aktif').length;
    const draft = list.filter(s => s.status === 'Draft').length;
    const menuSet = new Set();
    list.forEach(s => s.items && s.items.forEach(it => { if (it.menu_id) menuSet.add(it.menu_id); }));
    document.getElementById('stat-total').textContent = total;
    document.getElementById('stat-aktif').textContent = aktif;
    document.getElementById('stat-draft').textContent = draft;
    document.getElementById('stat-menu').textContent = menuSet.size || 0;
    statsEl.classList.remove('hidden');
  }

  if (!list.length) {
    wrap.innerHTML = '<div class="col-span-full text-center py-16 text-stone-400"><svg class="w-14 h-14 mx-auto mb-3 text-stone-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"/><rect x="8" y="2" width="8" height="4" rx="1" ry="1"/></svg><div>Belum ada siklus menu</div></div>';
    return;
  }

  var selectAllHtml = '<div class="col-span-full flex items-center gap-3 py-1">' +
    '<label class="flex items-center gap-2 text-sm text-stone-500 cursor-pointer">' +
      '<input type="checkbox" id="siklus-select-all" onchange="toggleSelectAll(this)" class="w-4 h-4 rounded border-stone-300 text-[#1e40af] focus:ring-[#1e40af]/30">' +
      'Pilih Semua' +
    '</label>' +
  '</div>';

  wrap.innerHTML = selectAllHtml + list.map(s => {
    const statusColor = s.status === 'Aktif' ? 'bg-emerald-100 text-emerald-800' : s.status === 'Draft' ? 'bg-amber-100 text-amber-800' : 'bg-stone-100 text-stone-600';
    const menuCount = (s.items || []).filter(it => it.menu_id).length;
    return `<div class="bg-white border border-stone-200 rounded-xl p-5 hover:shadow-lg hover:border-stone-300 transition-all duration-200 group">
      <div class="flex justify-between items-start mb-3">
        <div class="flex items-center gap-3 min-w-0">
          <input type="checkbox" value="${s.id}" onchange="updateSelectedCount()" onclick="event.stopPropagation()" class="siklus-checkbox w-4 h-4 rounded border-stone-300 text-[#1e40af] focus:ring-[#1e40af]/30 shrink-0">
          <div class="font-semibold text-sm text-stone-800 group-hover:text-[#1e40af] transition-colors cursor-pointer" onclick="loadSiklusDetail(${s.id})">${s.nama}</div>
        </div>
        <span class="text-[10px] px-2.5 py-1 rounded-full font-medium ${statusColor} capitalize">${s.status}</span>
      </div>
      <div class="flex items-center gap-4 text-xs text-stone-500 mb-3">
        <span class="flex items-center gap-1"><svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/></svg>${s.kategori_penerima || 'Semua'}</span>
        <span class="flex items-center gap-1"><svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/></svg>${s.jumlah_porsi} porsi/hari</span>
        <span class="flex items-center gap-1"><svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>${s.total_hari} hari</span>
      </div>
      ${s.catatan ? `<div class="text-xs text-stone-400 italic mb-3 line-clamp-1">${s.catatan}</div>` : ''}
      <div class="flex items-center justify-between pt-3 border-t border-stone-100">
        <div class="text-xs text-stone-400">${menuCount} menu terisi</div>
        <div class="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
          <button onclick="event.stopPropagation();loadSiklusDetail(${s.id})" class="px-2.5 py-1 text-xs font-medium text-blue-600 hover:bg-blue-50 rounded-lg transition-colors">Detail</button>
          <button onclick="event.stopPropagation();renderSiklusLaporan(${s.id})" class="px-2.5 py-1 text-xs font-medium text-emerald-600 hover:bg-emerald-50 rounded-lg transition-colors">Laporan</button>
          <button onclick="event.stopPropagation();editSiklus(${s.id})" class="px-2.5 py-1 text-xs font-medium text-stone-600 hover:bg-stone-100 rounded-lg transition-colors">Edit</button>
          <button onclick="event.stopPropagation();deleteSiklus(${s.id})" class="px-2.5 py-1 text-xs font-medium text-red-600 hover:bg-red-50 rounded-lg transition-colors">Hapus</button>
        </div>
      </div>
    </div>`;
  }).join('');
}

async function loadSiklusDetail(id) {
  const data = await api.get('/siklus/' + id);
  const wrap = document.getElementById('siklus-detail');
  wrap.innerHTML = `
    <div class="bg-white border border-stone-200 rounded-lg p-5">
      <div class="flex justify-between items-center mb-4">
        <div>
          <h3 class="font-bold text-lg">${data.nama}</h3>
          <div class="text-xs text-stone-500 mt-1">Kategori: <b>${data.kategori_penerima || '-'}</b> • Porsi/hari: <b>${fmtNum(data.jumlah_porsi)}</b> • Status: <b class="capitalize">${data.status}</b></div>
          ${data.catatan ? `<div class="text-xs text-stone-400 mt-1">${data.catatan}</div>` : ''}
        </div>
        <div class="flex flex-wrap gap-2">
          <button onclick="renderSiklusLaporan(${data.id})" class="px-3 py-1.5 text-sm border border-stone-300 rounded hover:bg-stone-50"><svg class="w-4 h-4 -mt-0.5 inline" fill="none" stroke="currentColor" viewBox="0 0 24 24"><line x1="18" y1="20" x2="18" y2="10"/><line x1="12" y1="20" x2="12" y2="4"/><line x1="6" y1="20" x2="6" y2="14"/></svg> Laporan</button>
          <button onclick="editSiklus(${data.id})" class="px-3 py-1.5 text-sm border border-stone-300 rounded hover:bg-stone-50">Edit Siklus</button>
          <button onclick="document.getElementById('siklus-detail').innerHTML=''" class="px-3 py-1.5 text-sm text-stone-500 hover:text-stone-900">Tutup</button>
        </div>
      </div>
      <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3">
        ${data.items.map(it => {
          const totalK = Number(it.kalori || 0) + Number(it.protein || 0) + Number(it.karbohidrat || 0) + Number(it.lemak || 0) + Number(it.serat || 0);
          return `<div class="border border-stone-200 rounded-lg p-4">
            <div class="text-xs font-semibold uppercase text-stone-500 mb-2">Hari ${it.hari_ke} — ${it.hari_nama}</div>
            <div class="font-bold text-sm mb-1">${it.menu_nama || '<span class="text-stone-400">Belum diisi</span>'}</div>
            <div class="text-xs text-stone-500 mb-2">${fmtNum(it.jumlah_porsi)} porsi</div>
            ${it.menu_nama ? `<div class="grid grid-cols-3 gap-1 text-[10px] mb-2">
              <div class="bg-stone-50 rounded p-1 text-center"><div class="text-stone-400">Kal</div><div class=\"mono font-semibold\">${fmtNum(it.kalori)}</div></div>
              <div class="bg-stone-50 rounded p-1 text-center"><div class="text-stone-400">Prot</div><div class=\"mono font-semibold\">${fmtNum(it.protein)}</div></div>
              <div class="bg-stone-50 rounded p-1 text-center"><div class="text-stone-400">Karb</div><div class=\"mono font-semibold\">${fmtNum(it.karbohidrat)}</div></div>
              <div class="bg-stone-50 rounded p-1 text-center"><div class="text-stone-400">Lem</div><div class=\"mono font-semibold\">${fmtNum(it.lemak)}</div></div>
              <div class="bg-stone-50 rounded p-1 text-center"><div class="text-stone-400">Ser</div><div class=\"mono font-semibold\">${fmtNum(it.serat)}</div></div>
            </div>` : ''}
            <div id="sk-dtl-bd-${it.hari_ke}" class="text-[10px] text-stone-400 animate-pulse">Memuat kategori...</div>
          </div>`;
        }).join('')}
      </div>
    </div>`;
  // Load category breakdown for each day
  for (const it of data.items) {
    if (it.menu_id) {
      const groups = await getMenuKategoriBreakdown(it.menu_id);
      const el = document.getElementById('sk-dtl-bd-' + it.hari_ke);
      if (el) el.innerHTML = renderKategoriBreakdown(groups) || '<div class="text-stone-400 text-[10px]">Tidak ada data bahan</div>';
    } else {
      const el = document.getElementById('sk-dtl-bd-' + it.hari_ke);
      if (el) el.innerHTML = '';
    }
  }
}

