// ===== Perhitungan BDD & Kebutuhan Bahan Pangan per Menu (Khusus Ahli Gizi) =====
async function renderPerhitunganBdd() {
  const c = document.getElementById('content');
  c.innerHTML = '<div class="flex items-center justify-center py-24"><svg class="animate-spin h-10 w-10 text-emerald-600" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"/><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"/></svg></div>';
  try {
    const r = await fetch('/api/template/perhitungan-bdd', { credentials: 'include' });
    if (!r.ok) throw new Error((await r.json()).error || 'Gagal memuat');
    c.innerHTML = await r.text();
    await loadPbdData();
  } catch (err) {
    c.innerHTML = '<div class="bg-red-50 border border-red-200 text-red-700 p-4 rounded-lg">Gagal memuat: ' + err.message + '</div>';
  }
}

async function loadPbdData(siklusId) {
  const wrap = document.getElementById('pbd-content');
  if (!wrap) return;
  wrap.innerHTML = '<div class="flex items-center justify-center py-16"><svg class="animate-spin h-8 w-8 text-emerald-600" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"/><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"/></svg></div>';

  try {
    const params = siklusId ? '?siklus_id=' + siklusId : '';
    const res = await api.get('/siklus/laporan/kebutuhan-per-menu' + params);
    const { siklus_list, selected_siklus_id, jenjang_list, data } = res;

    let html = '';

    // Filter Siklus
    html += renderPbdFilter(siklus_list, selected_siklus_id);

    if (!data || !data.length) {
      html += '<div class="text-center py-16 text-stone-400 bg-white border border-stone-200 rounded-lg"><svg class="w-14 h-14 mx-auto mb-3 text-stone-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><rect x="2" y="3" width="20" height="18" rx="2" ry="2"/><path d="M12 17v-6"/><circle cx="12" cy="21" r="2"/></svg><div class="text-sm">Tidak ada data untuk ditampilkan</div><div class="text-xs mt-1">Pilih siklus dengan status Aktif atau pastikan Penerima Manfaat sudah diisi.</div></div>';
      wrap.innerHTML = html;
      return;
    }

    // Render per jenjang
    for (var j = 0; j < data.length; j++) {
      var jd = data[j];
      html += renderPbdJenjangSection(jd);
    }

    // Legenda
    html += '<div class="bg-white border border-stone-200 rounded-lg p-4 mt-4 text-xs text-stone-500">';
    html += '<div class="font-semibold text-stone-700 mb-2">Keterangan:</div>';
    html += '<ul class="space-y-1 list-disc list-inside">';
    html += '<li><strong>Berat Bersih</strong> = Jumlah bahan per porsi (gram) — dihitung dari SP × Berat 1 SP atau dari data Menu</li>';
    html += '<li><strong>BDD%</strong> = <em>Bahan Dapat Dimakan</em> — persentase bagian yang dapat dikonsumsi. Sumber: <span class="text-emerald-600 font-medium">SP Referensi</span> (prioritas) atau data <span class="text-stone-500">Bahan Baku</span></li>';
    html += '<li><strong>Berat Kotor</strong> = Berat Bersih ÷ (BDD ÷ 100)</li>';
    html += '<li><strong>Kebutuhan (kg)</strong> = Berat Kotor × Jumlah Siswa ÷ 1000</li>';
    html += '</ul></div>';

    wrap.innerHTML = html;
  } catch (err) {
    wrap.innerHTML = '<div class="bg-red-50 border border-red-200 text-red-700 p-4 rounded-lg">Gagal: ' + err.message + '</div>';
  }
}

function renderPbdFilter(siklusList, selectedId) {
  var html = '<div class="bg-white border border-stone-200 rounded-lg p-4 mb-4 flex flex-wrap items-center gap-4">';
  html += '<label class="text-sm font-medium text-stone-700">Filter Siklus:</label>';
  html += '<select onchange="loadPbdData(this.value)" class="h-10 px-3 border border-stone-200 rounded-xl text-sm bg-white min-w-[200px] focus:ring-2 focus:ring-emerald-500/20 focus:border-emerald-400">';
  html += '<option value="">— Semua Siklus Aktif —</option>';
  for (var i = 0; i < siklusList.length; i++) {
    var s = siklusList[i];
    html += '<option value="' + s.id + '" ' + (selectedId && Number(selectedId) === s.id ? 'selected' : '') + '>' + s.nama + ' (' + s.status + ')' + '</option>';
  }
  html += '</select>';
  html += '<div class="text-xs text-stone-400 ml-auto">' + siklusList.length + ' siklus tersedia</div>';
  html += '</div>';
  return html;
}

function renderPbdJenjangSection(jd) {
  var html = '<div class="bg-white border border-stone-200 rounded-lg overflow-hidden mb-6">';

  // Jenjang header
  var jColors = ['bg-blue-50 text-blue-800', 'bg-emerald-50 text-emerald-800', 'bg-amber-50 text-amber-800', 'bg-violet-50 text-violet-800', 'bg-cyan-50 text-cyan-800', 'bg-rose-50 text-rose-800'];
  var jIdx = ['TK/PAUD','SD/MI (1-3)','SD/MI (4-6)','SMP/MTs, SMA/SMK','Bumil/Busui','Balita'].indexOf(jd.jenjang);
  if (jIdx < 0) jIdx = 0;
  html += '<div class="px-5 py-4 border-b border-stone-200 flex items-center justify-between ' + jColors[jIdx % jColors.length] + '">';
  html += '<div><span class="font-bold text-base">' + jd.jenjang + '</span>';
  html += '<span class="ml-3 text-sm font-normal">Jumlah Siswa: <strong>' + fmtPbdNum(jd.jumlah_siswa) + '</strong> orang</span></div>';
  html += '<div class="text-xs">' + jd.siklus.length + ' siklus</div>';
  html += '</div>';

  // Per siklus
  for (var s = 0; s < jd.siklus.length; s++) {
    var sk = jd.siklus[s];

    // Siklus sub-header
    html += '<div class="px-5 py-2 bg-stone-50 border-b border-stone-200 text-sm font-semibold text-stone-600 flex items-center gap-2">';
    html += '<svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>';
    html += sk.siklus_nama;
    html += '</div>';

    // Per hari
    for (var h = 0; h < sk.hari.length; h++) {
      var day = sk.hari[h];
      html += renderPbdMenuTable(day, jd.jumlah_siswa);
    }
  }

  html += '</div>';
  return html;
}

function renderPbdMenuTable(day, jumlahSiswa) {
  var html = '<div class="px-5 py-3 border-b border-stone-100 bg-stone-50/30">';

  // Menu header
  html += '<div class="flex items-center gap-3 mb-2">';
  html += '<span class="inline-block px-3 py-1 rounded-lg bg-emerald-100 text-emerald-800 text-sm font-bold">' + day.menu_label + '</span>';
  html += '<span class="text-sm font-semibold text-stone-700">' + day.hari_nama + '</span>';
  html += '<span class="text-xs text-stone-400">' + (day.menu_nama || '') + '</span>';
  html += '</div>';

  if (!day.bahan || !day.bahan.length) {
    html += '<div class="text-xs text-stone-400 italic px-2 pb-2">Tidak ada bahan</div></div>';
    return html;
  }

  // Table
  html += '<div class="overflow-x-auto pb-2"><table class="w-full text-xs border-collapse">';
  html += '<thead><tr class="border-b border-stone-200">';
  html += '<th class="px-2 py-1.5 text-left font-semibold text-stone-600 min-w-[140px]">Bahan Pangan</th>';
  html += '<th class="px-2 py-1.5 text-right font-semibold text-stone-600 whitespace-nowrap">Berat Bersih (g)</th>';
  html += '<th class="px-2 py-1.5 text-right font-semibold text-stone-600 whitespace-nowrap">BDD (%)</th>';
  html += '<th class="px-2 py-1.5 text-right font-semibold text-stone-600 whitespace-nowrap">Berat Kotor (g)</th>';
  html += '<th class="px-2 py-1.5 text-right font-semibold text-stone-600 whitespace-nowrap">Jumlah Siswa</th>';
  html += '<th class="px-2 py-1.5 text-right font-semibold text-stone-600 whitespace-nowrap">Kebutuhan (kg)</th>';
  html += '</tr></thead><tbody>';

  for (var i = 0; i < day.bahan.length; i++) {
    var b = day.bahan[i];
    var sumberBdd = b.sumber_bdd === 'sp_referensi';
    html += '<tr class="border-b border-stone-100 hover:bg-stone-50/50">';
    html += '<td class="px-2 py-1.5 text-sm font-medium">' + b.nama_display + '</td>';
    html += '<td class="px-2 py-1.5 text-sm text-right mono">' + fmtPbdNum(b.berat_bersih) + '</td>';
    html += '<td class="px-2 py-1.5 text-sm text-right mono ' + (sumberBdd ? 'text-emerald-600 font-semibold' : '') + '">' + b.persen_bdd + '%</td>';
    html += '<td class="px-2 py-1.5 text-sm text-right mono">' + fmtPbdNum(b.berat_kotor) + '</td>';
    html += '<td class="px-2 py-1.5 text-sm text-right mono">' + fmtPbdNum(jumlahSiswa) + '</td>';
    html += '<td class="px-2 py-1.5 text-sm text-right mono font-bold text-emerald-700">' + fmtPbdNum(b.kebutuhan_kg) + '</td>';
    html += '</tr>';
  }

  html += '</tbody></table></div></div>';
  return html;
}

function fmtPbdNum(v) {
  if (v == null || isNaN(v)) return '0,00';
  return Number(v).toFixed(2).replace('.', ',');
}

function exportPbdCsv() {
  showAlert('Export CSV: gunakan Print atau salin dari tabel', 'info');
}

// ===== BDD Kalkulator — Real-time BDD Calculator =====
// Modul ini menyediakan kalkulator interaktif untuk menghitung:
//   - Berat Kotor  = Berat Bersih / (BDD / 100)
//   - Berat Bersih = Berat Kotor * (BDD / 100)
//   - Kebutuhan Bahan (kg) = (Berat Kotor * Jumlah Siswa) / 1000
// Semua perhitungan berjalan real-time tanpa reload halaman.

/**
 * Memformat angka ke maksimal 2 desimal tanpa trailing zero yang tidak perlu
 * @param {number} nilai - Angka yang akan diformat
 * @returns {string} Angka yang diformat dengan maksimal 2 desimal
 */
function fmt2(nilai) {
  return Number(nilai || 0).toFixed(2);
}

/**
 * Menghitung berat kotor dari berat bersih dan persen BDD
 * Rumus: Berat Kotor = Berat Bersih / (BDD / 100)
 * @param {number} beratBersih - Berat bersih dalam gram
 * @param {number} bddPersen - Persen BDD (1-100)
 * @returns {number} Berat kotor dalam gram, dibulatkan ke bilangan bulat terdekat
 */
function hitungBeratKotor(beratBersih, bddPersen) {
  if (!beratBersih || beratBersih <= 0) return 0;
  if (!bddPersen || bddPersen <= 0) return beratBersih;
  var faktor = bddPersen / 100;
  return Math.round(beratBersih / faktor);
}

/**
 * Menghitung berat bersih dari berat kotor dan persen BDD
 * Rumus: Berat Bersih = Berat Kotor * (BDD / 100)
 * @param {number} beratKotor - Berat kotor dalam gram
 * @param {number} bddPersen - Persen BDD (1-100)
 * @returns {number} Berat bersih dalam gram, maksimal 2 desimal
 */
function hitungBeratBersih(beratKotor, bddPersen) {
  if (!beratKotor || beratKotor <= 0) return 0;
  if (!bddPersen || bddPersen <= 0) return 0;
  var faktor = bddPersen / 100;
  return parseFloat((beratKotor * faktor).toFixed(2));
}

/**
 * Menghitung kebutuhan bahan dalam kilogram
 * Rumus: Kebutuhan (kg) = (Berat Kotor * Jumlah Siswa) / 1000
 * @param {number} beratKotor - Berat kotor per porsi dalam gram
 * @param {number} jumlahSiswa - Jumlah siswa/penerima manfaat
 * @returns {number} Kebutuhan bahan dalam kg, maksimal 2 desimal
 */
function hitungKebutuhanBahan(beratKotor, jumlahSiswa) {
  if (!beratKotor || beratKotor <= 0) return 0;
  if (!jumlahSiswa || jumlahSiswa < 1) return 0;
  return parseFloat(((beratKotor * jumlahSiswa) / 1000).toFixed(2));
}

/**
 * Memvalidasi nilai BDD berada dalam rentang 1-100%
 * @param {number|string} nilai - Nilai BDD yang akan divalidasi
 * @returns {{valid: boolean, pesan: string}} Hasil validasi
 */
function validasiBdd(nilai) {
  var num = Number(nilai);
  if (isNaN(num) || num < 1) {
    return { valid: false, pesan: 'BDD minimal 1%' };
  }
  if (num > 100) {
    return { valid: false, pesan: 'BDD maksimal 100%' };
  }
  return { valid: true, pesan: '' };
}

/**
 * Memvalidasi nilai berat tidak boleh negatif
 * @param {number|string} nilai - Nilai berat yang akan divalidasi
 * @returns {{valid: boolean, pesan: string}} Hasil validasi
 */
function validasiBerat(nilai) {
  var num = Number(nilai);
  if (isNaN(num) || num < 0) {
    return { valid: false, pesan: 'Berat tidak boleh negatif' };
  }
  return { valid: true, pesan: '' };
}

/**
 * Memvalidasi jumlah siswa minimal 1
 * @param {number|string} nilai - Jumlah siswa yang akan divalidasi
 * @returns {{valid: boolean, pesan: string}} Hasil validasi
 */
function validasiSiswa(nilai) {
  var num = Number(nilai);
  if (isNaN(num) || num < 1) {
    return { valid: false, pesan: 'Jumlah siswa minimal 1' };
  }
  return { valid: true, pesan: '' };
}

/**
 * Memperbarui seluruh hasil perhitungan di UI secara real-time
 */
function perbaruiHasil() {
  // Ambil nilai input dari form
  var beratBersih = parseFloat(document.getElementById('bdd-berat-bersih').value) || 0;
  var bddPersen = parseFloat(document.getElementById('bdd-persen').value) || 0;
  var beratKotor = parseFloat(document.getElementById('bdd-berat-kotor').value) || 0;
  var jumlahSiswa = parseInt(document.getElementById('bdd-jumlah-siswa').value) || 0;
  var mode = document.getElementById('bdd-mode').value;

  // Validasi tiap input dan tampilkan error
  var vBdd = validasiBdd(bddPersen);
  var vBeratBersih = validasiBerat(beratBersih);
  var vBeratKotor = validasiBerat(beratKotor);
  var vSiswa = validasiSiswa(jumlahSiswa);

  document.getElementById('bdd-error-bdd').textContent = vBdd.valid ? '' : vBdd.pesan;
  document.getElementById('bdd-error-bersih').textContent = vBeratBersih.valid ? '' : vBeratBersih.pesan;
  document.getElementById('bdd-error-kotor').textContent = vBeratKotor.valid ? '' : vBeratKotor.pesan;
  document.getElementById('bdd-error-siswa').textContent = vSiswa.valid ? '' : vSiswa.pesan;

  // Hanya hitung jika BDD valid
  if (!vBdd.valid) {
    document.getElementById('bdd-hasil-kotor').textContent = '0';
    document.getElementById('bdd-hasil-bersih').textContent = '0';
    document.getElementById('bdd-hasil-kebutuhan').textContent = '0';
    return;
  }

  var hasilKotor = 0;
  var hasilBersih = 0;

  if (mode === 'ke-kotor') {
    // Mode: Berat Bersih & BDD -> Berat Kotor
    if (vBeratBersih.valid && beratBersih > 0) {
      hasilKotor = hitungBeratKotor(beratBersih, bddPersen);
      hasilBersih = beratBersih;
    }
  } else {
    // Mode: Berat Kotor & BDD -> Berat Bersih
    if (vBeratKotor.valid && beratKotor > 0) {
      hasilBersih = hitungBeratBersih(beratKotor, bddPersen);
      hasilKotor = beratKotor;
    }
  }

  // Tampilkan hasil berat kotor dan bersih
  document.getElementById('bdd-hasil-kotor').textContent = fmt2(hasilKotor);
  document.getElementById('bdd-hasil-bersih').textContent = fmt2(hasilBersih);

  // Hitung kebutuhan bahan dalam kg
  var kebutuhan = 0;
  if (vSiswa.valid && hasilKotor > 0) {
    kebutuhan = hitungKebutuhanBahan(hasilKotor, jumlahSiswa);
  }
  document.getElementById('bdd-hasil-kebutuhan').textContent = fmt2(kebutuhan);

  // Tampilkan breakdown rumus
  var faktorBdd = bddPersen / 100;
  if (mode === 'ke-kotor' && beratBersih > 0) {
    document.getElementById('bdd-rumus-kotor').textContent =
      beratBersih + ' / (' + bddPersen + ' / 100) = ' + beratBersih + ' / ' + fmt2(faktorBdd) + ' = ' + hasilKotor;
  } else if (beratKotor > 0) {
    document.getElementById('bdd-rumus-kotor').textContent =
      beratKotor + ' x (' + bddPersen + ' / 100) = ' + beratKotor + ' x ' + fmt2(faktorBdd) + ' = ' + fmt2(hasilBersih);
  } else {
    document.getElementById('bdd-rumus-kotor').textContent = '—';
  }

  if (vSiswa.valid && hasilKotor > 0) {
    document.getElementById('bdd-rumus-kebutuhan').textContent =
      hasilKotor + ' x ' + jumlahSiswa + ' / 1000 = ' + (hasilKotor * jumlahSiswa) + ' / 1000 = ' + fmt2(kebutuhan);
  } else {
    document.getElementById('bdd-rumus-kebutuhan').textContent = '—';
  }
}

/**
 * Mengganti mode kalkulator (ke berat kotor atau ke berat bersih)
 */
function gantiModeBdd() {
  var mode = document.getElementById('bdd-mode').value;
  var grupBersih = document.getElementById('bdd-grup-bersih');
  var grupKotor = document.getElementById('bdd-grup-kotor');

  if (mode === 'ke-kotor') {
    grupBersih.classList.remove('opacity-50', 'pointer-events-none');
    grupKotor.classList.add('opacity-50', 'pointer-events-none');
    document.getElementById('bdd-mode-label').textContent =
      'Menghitung Berat Kotor dari Berat Bersih dan BDD';
  } else {
    grupKotor.classList.remove('opacity-50', 'pointer-events-none');
    grupBersih.classList.add('opacity-50', 'pointer-events-none');
    document.getElementById('bdd-mode-label').textContent =
      'Menghitung Berat Bersih dari Berat Kotor dan BDD';
  }
  perbaruiHasil();
}

/**
 * Memuat daftar bahan dari database sp_referensi_bahan
 * dan mengisi nilai BDD + berat bersih saat dipilih
 */
async function muatDaftarBahan() {
  var select = document.getElementById('bdd-pilih-bahan');
  if (!select) return;
  select.innerHTML = '<option value="">— Muat data... —</option>';
  try {
    var res = await api.get('/sp_referensi_bahan?limit=9999');
    var list = Array.isArray(res) ? res : (res.data || []);
    select.innerHTML = '<option value="">— Pilih Bahan (isi otomatis) —</option>' +
      list.map(function(b) {
        return '<option value="' + b.id + '" ' +
          'data-bdd="' + (Math.round((b.bdd_persen || 0) * 100)) + '" ' +
          'data-bersih="' + (b.berat_bersih || 0) + '" ' +
          'data-kotor="' + (b.berat_kotor || 0) + '" ' +
          'data-nama="' + (b.nama || '') + '">' +
          (b.nama || '') + ' — BDD ' + Math.round((b.bdd_persen || 0) * 100) +
          '% — Bersih ' + (b.berat_bersih || 0) + 'g' +
          '</option>';
      }).join('');
  } catch (e) {
    select.innerHTML = '<option value="">Gagal memuat data</option>';
    showToast('Gagal memuat bahan: ' + e.message, 'error');
  }
}

/**
 * Mengisi form dari bahan yang dipilih di dropdown
 */
function isiDariBahan() {
  var select = document.getElementById('bdd-pilih-bahan');
  var opt = select.options[select.selectedIndex];
  if (!opt || !opt.value) return;

  var bdd = parseInt(opt.dataset.bdd) || 0;
  var bersih = parseFloat(opt.dataset.bersih) || 0;
  var kotor = parseFloat(opt.dataset.kotor) || 0;

  document.getElementById('bdd-persen').value = bdd;
  document.getElementById('bdd-berat-bersih').value = bersih;

  var mode = document.getElementById('bdd-mode').value;
  if (mode === 'ke-kotor') {
    document.getElementById('bdd-berat-bersih').value = bersih;
  } else {
    document.getElementById('bdd-berat-kotor').value = kotor;
  }

  document.getElementById('bdd-nama-terpilih').textContent = opt.dataset.nama || '';
  perbaruiHasil();
}

